INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Befehl immer die MAC-Adresse anzeigt?', 2, '[{"text": "Ja", "correct": true, "because": "Mit /all sichtbar"}, {"text": "Nein", "correct": false, "because": "Standard zeigt sie"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Option zeigt dir detaillierte Netzwerkinfos?', 3, '[{"text": "/all", "correct": true, "because": "Liefert vollständige Details"}, {"text": "/release", "correct": false, "because": "Nur IP freigeben"}, {"text": "/renew", "correct": false, "because": "Nur IP erneuern"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Infos liefert ein Netzwerkbefehl mit Standardeinstellung?', 5, '[{"text": "IP-Adresse", "correct": true, "because": "Grundlegende Info"}, {"text": "Subnetzmaske", "correct": true, "because": "Netzwerksegment"}, {"text": "Standardgateway", "correct": true, "because": "Routing-Info"}, {"text": "Büroverschönerung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) /release gibt die IP-Adresse frei. b) /all zeigt nur die IP-Adresse.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "/all zeigt mehr"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich Netzwerkeinstellungen prüfe?', 4, '[{"text": "IP-Adresse", "correct": false, "because": "Kerninformation"}, {"text": "DNS-Server", "correct": false, "because": "Wichtig für Namensauflösung"}, {"text": "Büroverschönerung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein Befehl nur auf Linux läuft. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Windows-spezifisch"}, {"text": "Ja", "correct": false, "because": "Falsche Plattform"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Option erneuert die Netzwerkkonfiguration?', 3, '[{"text": "/renew", "correct": true, "because": "Holt neue IP"}, {"text": "/release", "correct": false, "because": "Gibt IP frei"}, {"text": "/displaydns", "correct": false, "because": "Zeigt DNS-Cache"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein Netzwerkbefehl mit /all?', 5, '[{"text": "Vollständige Infos", "correct": true, "because": "Zeigt alles"}, {"text": "MAC-Adresse", "correct": true, "because": "Physische Adresse"}, {"text": "DNS-Server", "correct": true, "because": "Auflösung sichtbar"}, {"text": "Farbanpassung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass a) /release die IP freigibt und b) /renew nur für IPv6 ist. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "/renew für beide"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um Netzwerkeinstellungen zu prüfen?', 4, '[{"text": "Eingabeaufforderung", "correct": false, "because": "Befehl ausführen"}, {"text": "Netzwerkadapter", "correct": false, "because": "Liefert Daten"}, {"text": "Grafikdesign", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Zeigt ein Standardbefehl den DNS-Server?', 2, '[{"text": "Nein", "correct": true, "because": "Nur mit /all"}, {"text": "Ja", "correct": false, "because": "Standard ist begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Infos helfen bei der Netzwerkdiagnose?', 4, '[{"text": "IP-Adresse", "correct": true, "because": "Identifiziert Gerät"}, {"text": "Gateway", "correct": true, "because": "Routing prüfen"}, {"text": "Farbanpassung", "correct": false, "because": "Kein Netzwerkfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein Befehl nur IPv4 zeigt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch IPv6 möglich"}, {"text": "Ja", "correct": false, "because": "Beide Versionen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einem Netzwerkbefehl?', 3, '[{"text": "Netzwerkprobleme finden", "correct": true, "because": "Diagnose unterstützt"}, {"text": "Design verbessern", "correct": false, "because": "Sekundär"}, {"text": "Daten komprimieren", "correct": false, "because": "Anderer Zweck"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) /displaydns zeigt den DNS-Cache. b) /release erneuert die IP.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "/release gibt frei"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt /flushdns?', 4, '[{"text": "DNS-Cache leeren", "correct": true, "because": "Löscht Einträge"}, {"text": "IP-Adresse freigeben", "correct": false, "because": "Andere Option"}, {"text": "Gateway ändern", "correct": false, "because": "Nicht möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Befehl die MAC-Adresse ohne Optionen zeigt?', 2, '[{"text": "Nein", "correct": true, "because": "Nur mit /all"}, {"text": "Ja", "correct": false, "because": "Standard begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein Netzwerkbefehl?', 5, '[{"text": "Schnelle Diagnose", "correct": true, "because": "Zeigt Konfiguration"}, {"text": "IP-Problembehebung", "correct": true, "because": "Mit /renew"}, {"text": "Detaillierte Infos", "correct": true, "because": "Mit /all"}, {"text": "Datenkompression", "correct": false, "because": "Kein Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist /flushdns für IP-Probleme?', 3, '[{"text": "Nein", "correct": true, "because": "Nur DNS-Cache"}, {"text": "Ja", "correct": false, "because": "DNS-spezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario passt zu einem Netzwerkbefehl?', 4, '[{"text": "Verbindung prüfen", "correct": true, "because": "Zeigt IP-Details"}, {"text": "Webseite designen", "correct": false, "because": "Anderer Zweck"}, {"text": "Daten komprimieren", "correct": false, "because": "Nicht relevant"}]');
